{
  "type": "object",
  "properties": {
    "severity": {
      "type": "string",
      "enum": [
        "Critical",
        "High",
        "Medium",
        "Low"
      ]
    },
    "business_impact": {
      "type": "string",
      "enum": [
        "Critical Business Impact",
        "High Business Impact",
        "Moderate Business Impact",
        "Low Business Impact"
      ]
    },
    "affected_users": {
      "type": "string",
      "enum": [
        "Enterprise Wide",
        "Thousands",
        "Hundreds",
        "Tens",
        "Few",
        "Unknown"
      ]
    },
    "sla_response": {
      "type": "string",
      "enum": [
        "Immediate",
        "15 Minutes",
        "30 Minutes",
        "1 Hour",
        "4 Hours",
        "Next Business Day"
      ]
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
