parameters.jsCode:
const j = $input.first().json;
let o = j.output ?? j;
if (typeof o === 'string') {
  try { o = JSON.parse(o); } catch (e) { throw new Error('Invalid agent JSON: ' + o); }
}
return [{ json: o }];

const o=$input.first().json;
const base=$('When Executed by Another Workflow').item.json;
const incident=base.incident || {};
return [{json:{incident,incident_id:incident.incident_id||'',title:incident.title||'',description:incident.description||'',service:incident.service||incident.serviceType||'',incident_type:base.incident_type||'',category:base.category||'',priority:base.priority||'',classification_confidence:base.classification_confidence??null,...o}}];
